macro_rules! extract_fn_def_from_const_callable {
    () => {
        # [doc = " This duplicates `extract_tupled_inputs_and_output_from_callable` but needs"] # [doc = " to return different information (namely, the def id and args) so that we can"] # [doc = " create const conditions."] # [doc = ""] # [doc = " Doing so on all calls to `extract_tupled_inputs_and_output_from_callable`"] # [doc = " would be wasteful."] pub (in crate :: solve) fn extract_fn_def_from_const_callable < I : Interner > (cx : I , self_ty : I :: Ty ,) -> Result < (ty :: Binder < I , (I :: FnInputTys , I :: Ty) > , I :: FunctionId , I :: GenericArgs) , NoSolution > { match self_ty . kind () { ty :: FnDef (def_id , args) => { let sig = cx . fn_sig (def_id) ; if sig . skip_binder () . is_fn_trait_compatible () && ! cx . has_target_features (def_id) && cx . fn_is_const (def_id) { Ok ((sig . instantiate (cx , args) . map_bound (| sig | (sig . inputs () , sig . output ())) , def_id , args ,)) } else { return Err (NoSolution) ; } } ty :: FnPtr (..) => { return Err (NoSolution) ; } ty :: Closure (..) => { return Err (NoSolution) ; } ty :: CoroutineClosure (..) => { return Err (NoSolution) ; } ty :: Bool | ty :: Char | ty :: Int (_) | ty :: Uint (_) | ty :: Float (_) | ty :: Adt (_ , _) | ty :: Foreign (_) | ty :: Str | ty :: Array (_ , _) | ty :: Slice (_) | ty :: RawPtr (_ , _) | ty :: Ref (_ , _ , _) | ty :: Dynamic (_ , _ , _) | ty :: Coroutine (_ , _) | ty :: CoroutineWitness (..) | ty :: Never | ty :: Tuple (_) | ty :: Pat (_ , _) | ty :: Alias (_ , _) | ty :: Param (_) | ty :: Placeholder (..) | ty :: Infer (ty :: IntVar (_) | ty :: FloatVar (_)) | ty :: Error (_) | ty :: UnsafeBinder (_) => return Err (NoSolution) , ty :: Bound (..) | ty :: Infer (ty :: TyVar (_) | ty :: FreshTy (_) | ty :: FreshIntTy (_) | ty :: FreshFloatTy (_)) => { panic ! ("unexpected type `{self_ty:?}`") } } }
    };
}

extract_fn_def_from_const_callable!();